//! Replays `tests/fixtures/vcs-rpc.jsonl`, generated by `tools/generate_vcs_rpc_fixtures.mjs` from
//! the original contract schemas, worktree helpers, status back-off and `VcsDriverRegistry`.
use crate::{
    vcs_error::{VcsRpcError, vcs_error_wire},
    vcs_input,
    vcs_registry::VcsRegistry,
    vcs_status::remote_refresh_failure_delay,
    vcs_worktree::{parse_project_file, resolve_worktrees_directory_in},
};
use futures_util::future::BoxFuture;
use serde_json::{Value, json};
use std::{
    path::{Path, PathBuf},
    sync::{Arc, Mutex},
    time::Duration,
};
use t3_vcs::{
    GitVcs, ManualClock, VcsDriverKind, VcsError, VcsProcess,
    core::WorktreeSubmodules,
    error::ProcessContext,
    process::{ProcessRunError, ProcessRunInput, ProcessRunOutput, ProcessRunner},
};

fn rows(kind: &str) -> Vec<Value> {
    include_str!("../tests/fixtures/vcs-rpc.jsonl")
        .lines()
        .map(|line| serde_json::from_str::<Value>(line).unwrap())
        .filter(|row| row["type"] == kind)
        .collect()
}

#[test]
fn payloads_decode_and_fail_like_the_original_schemas() {
    let inputs = rows("input");
    assert!(inputs.len() > 120);
    for row in inputs {
        let (method, payload) = (row["method"].as_str().unwrap(), &row["payload"]);
        let decoded: Result<Value, String> = match method {
            "vcs.refreshStatus" | "vcs.pull" => {
                vcs_input::status_input(payload).map(|input| serde_json::to_value(input).unwrap())
            }
            "subscribeVcsStatus" => vcs_input::status_subscription_input(payload)
                .map(|input| serde_json::to_value(input).unwrap()),
            "vcs.listRefs" => vcs_input::list_refs_input(payload)
                .map(|input| serde_json::to_value(input).unwrap()),
            "vcs.createWorktree" => vcs_input::create_worktree_input(payload)
                .map(|input| serde_json::to_value(input).unwrap()),
            "vcs.removeWorktree" => vcs_input::remove_worktree_input(payload)
                .map(|input| serde_json::to_value(input).unwrap()),
            "vcs.createRef" => vcs_input::create_ref_input(payload)
                .map(|input| serde_json::to_value(input).unwrap()),
            "vcs.switchRef" => vcs_input::switch_ref_input(payload)
                .map(|input| serde_json::to_value(input).unwrap()),
            "vcs.init" => {
                vcs_input::init_input(payload).map(|input| serde_json::to_value(input).unwrap())
            }
            other => panic!("unknown method {other}"),
        };
        match (decoded, row.get("ok"), row.get("error")) {
            (Ok(value), Some(ok), _) => assert_eq!(&value, ok, "{method} {payload}"),
            (Err(message), _, Some(error)) => {
                assert_eq!(&Value::String(message), error, "{method} {payload}")
            }
            (decoded, ok, error) => panic!("{method} {payload}: {decoded:?} vs {ok:?} {error:?}"),
        }
    }
}

fn context(operation: &str) -> ProcessContext {
    ProcessContext {
        operation: operation.into(),
        command: "git".into(),
        cwd: "/repo".into(),
        argument_count: Some(3),
    }
}

fn io(message: &str) -> Arc<std::io::Error> {
    Arc::new(std::io::Error::other(message.to_string()))
}

fn vcs_error(name: &str) -> VcsError {
    use t3_vcs::error::{ExitFailureKind, OutputStream, ReadStream};
    let c = || context("GitVcsDriver.initRepository");
    match name {
        "VcsProcessSpawnError" => VcsError::ProcessSpawn {
            context: c(),
            cause: io("spawn git ENOENT"),
        },
        "VcsProcessSpawnErrorNoCount" => VcsError::ProcessSpawn {
            context: ProcessContext {
                operation: "o".into(),
                command: "git".into(),
                cwd: "/repo".into(),
                argument_count: None,
            },
            cause: io("x"),
        },
        "VcsProcessExitError" => VcsError::ProcessExit {
            context: c(),
            exit_code: 128,
            detail: "Process exited with a non-zero status.".into(),
            failure_kind: Some(ExitFailureKind::CommandFailed),
            retryable: false,
            stderr_length: Some(42),
            stderr_truncated: Some(false),
        },
        "VcsProcessExitErrorRetryable" => VcsError::ProcessExit {
            context: c(),
            exit_code: 1,
            detail: "d".into(),
            failure_kind: Some(ExitFailureKind::Authentication),
            retryable: true,
            stderr_length: Some(0),
            stderr_truncated: Some(true),
        },
        "VcsProcessExitErrorBare" => VcsError::ProcessExit {
            context: ProcessContext {
                operation: "o".into(),
                command: "git".into(),
                cwd: "/repo".into(),
                argument_count: None,
            },
            exit_code: 2,
            detail: "d".into(),
            failure_kind: None,
            retryable: false,
            stderr_length: None,
            stderr_truncated: None,
        },
        "VcsProcessTimeoutError" => VcsError::ProcessTimeout {
            context: c(),
            timeout_ms: 10_000,
        },
        "VcsProcessStdinWriteError" => VcsError::ProcessStdinWrite {
            context: c(),
            stdin_bytes: 12,
            cause: io("EPIPE"),
        },
        "VcsProcessOutputReadError" => VcsError::ProcessOutputRead {
            context: c(),
            stream: ReadStream::ExitCode,
            cause: io("closed"),
        },
        "VcsProcessOutputLimitError" => VcsError::ProcessOutputLimit {
            context: c(),
            stream: OutputStream::Stdout,
            max_bytes: 65_536,
            observed_bytes: 70_000,
        },
        "VcsProcessMissingExitCodeError" => VcsError::ProcessMissingExitCode { context: c() },
        "VcsRepositoryDetectionError" => detection(),
        "VcsUnsupportedOperationError" => unsupported(),
        "VcsUnsupportedOperationErrorJj" => VcsError::UnsupportedOperation {
            operation: "VcsDriverRegistry.get".into(),
            kind: VcsDriverKind::Jj,
            detail: "No jj VCS driver is registered.".into(),
        },
        other => panic!("unknown error {other}"),
    }
}

fn detection() -> VcsError {
    VcsError::RepositoryDetection {
        operation: "GitVcsDriver.detectRepository".into(),
        cwd: "/repo".into(),
        detail: "boom".into(),
    }
}
fn unsupported() -> VcsError {
    VcsError::UnsupportedOperation {
        operation: "VcsDriverRegistry.resolve".into(),
        kind: VcsDriverKind::Unknown,
        detail: "No supported VCS repository was detected at /repo.".into(),
    }
}

#[test]
fn error_envelopes_match_the_original_schemas() {
    for row in rows("vcsError") {
        let name = row["name"].as_str().unwrap();
        let error = vcs_error(name);
        assert_eq!(vcs_error_wire(&error), row["json"], "{name}");
        assert_eq!(VcsRpcError::Vcs(error).wire(), row["json"], "{name}");
    }
    for row in rows("managerError") {
        let manager = |cause: Option<&VcsError>| {
            VcsRpcError::manager(
                "GitWorkflowService.localStatus",
                "/repo",
                "Failed to detect a VCS repository for this Git workflow.",
                cause,
            )
        };
        let error = match row["name"].as_str().unwrap() {
            "withCause" => manager(Some(&detection())),
            "withoutCause" => manager(None),
            "unsupportedCause" => manager(Some(&unsupported())),
            other => panic!("{other}"),
        };
        assert_eq!(error.wire(), row["json"], "{}", row["name"]);
    }
    let route = |detail: &str, cause: Option<&VcsError>| {
        VcsRpcError::route("GitWorkflowService.switchRef", "/repo", detail, cause)
    };
    for row in rows("routeError") {
        let error = match row["name"].as_str().unwrap() {
            "withCause" => route(
                "Failed to resolve the VCS driver for this Git command.",
                Some(&unsupported()),
            ),
            "withoutCause" => route(
                "The GitWorkflowService.switchRef command currently supports Git repositories only; detected jj.",
                None,
            ),
            other => panic!("{other}"),
        };
        assert_eq!(error.wire(), row["json"], "{}", row["name"]);
    }
}

#[test]
fn worktree_locations_resolve_like_the_original() {
    for row in rows("worktreesDirectory") {
        let resolved = resolve_worktrees_directory_in(
            row["setting"].as_str().unwrap(),
            Path::new(row["defaultDir"].as_str().unwrap()),
            Some(Path::new("/home/fixture")),
        );
        let expected = row["resolved"].as_str().map(PathBuf::from);
        assert_eq!(resolved, expected, "{}", row["setting"]);
    }
}

#[test]
fn project_files_decode_like_the_original() {
    for row in rows("projectFile") {
        let contents = row["contents"].as_str().unwrap();
        let parsed = parse_project_file(contents).map(|file| {
            json!({"worktreeSubmodules": file.worktree_submodules.map(|mode| match mode {
                WorktreeSubmodules::Recursive => "recursive",
                WorktreeSubmodules::TopLevel => "top-level",
                WorktreeSubmodules::None => "none",
            })})
        });
        assert_eq!(parsed.unwrap_or(Value::Null), row["parsed"], "{contents:?}");
    }
}

#[test]
fn refresh_failures_back_off_like_the_original() {
    for row in rows("failureDelay") {
        let delay = remote_refresh_failure_delay(
            row["failures"].as_u64().unwrap() as u32,
            Duration::from_millis(row["configuredMs"].as_u64().unwrap()),
        );
        assert_eq!(
            delay.as_millis() as u64,
            row["delayMs"].as_u64().unwrap(),
            "{row}"
        );
    }
}

// ---- repository detection --------------------------------------------------------------------

/// Answers git like `VcsDriverRegistry.test.ts`: the nearest folder at or above the cwd, up to
/// `root`, that holds `.git` is the repository.
struct DiskGit {
    root: PathBuf,
    calls: Arc<Mutex<Vec<String>>>,
}

impl ProcessRunner for DiskGit {
    fn run(
        &self,
        input: ProcessRunInput,
    ) -> BoxFuture<'_, Result<ProcessRunOutput, ProcessRunError>> {
        let cwd = PathBuf::from(&input.args[1]);
        let command = input.args[2..].join(" ");
        self.calls.lock().unwrap().push(command.clone());
        let mut repo = Some(cwd.clone());
        while let Some(dir) = repo.clone() {
            if dir.join(".git").exists() {
                break;
            }
            repo = (dir != self.root).then(|| dir.parent().unwrap().to_path_buf());
        }
        let output = |code: i32, stdout: String, stderr: &str| ProcessRunOutput {
            code: Some(code),
            stdout,
            stderr: stderr.into(),
            ..ProcessRunOutput::default()
        };
        let result = match repo {
            None => output(128, String::new(), "fatal: not a git repository"),
            Some(repo) => match command.as_str() {
                "rev-parse --is-inside-work-tree" => output(0, "true\n".into(), ""),
                "rev-parse --show-toplevel" => output(0, format!("{}\n", repo.display()), ""),
                "rev-parse --git-common-dir" => {
                    let up = cwd.strip_prefix(&repo).unwrap().components().count();
                    output(0, format!("{}.git\n", "../".repeat(up)), "")
                }
                _ => output(0, String::new(), ""),
            },
        };
        Box::pin(async move { Ok(result) })
    }
}

fn relative_to(root: &Path, path: &str) -> String {
    match Path::new(path).strip_prefix(root) {
        Ok(relative) if relative.as_os_str().is_empty() => ".".into(),
        Ok(relative) => relative.to_string_lossy().into_owned(),
        Err(_) => path.to_string(),
    }
}

fn masked(value: Value, root: &Path) -> Value {
    serde_json::from_str(&value.to_string().replace(root.to_str().unwrap(), "$ROOT")).unwrap()
}

#[tokio::test]
async fn repository_detection_follows_the_original_registry() {
    let scenarios = rows("registry");
    assert!(scenarios.len() >= 10);
    for scenario in scenarios {
        let name = scenario["scenario"].as_str().unwrap();
        let temp = tempfile::tempdir().unwrap();
        let root = std::fs::canonicalize(temp.path()).unwrap();
        for entry in scenario["setup"].as_array().unwrap() {
            std::fs::create_dir_all(root.join(entry.as_str().unwrap())).unwrap();
        }
        for (file, contents) in scenario["files"].as_object().unwrap() {
            std::fs::write(root.join(file), contents.as_str().unwrap()).unwrap();
        }
        let calls = Arc::new(Mutex::new(Vec::new()));
        let runner = DiskGit {
            root: root.join(scenario["root"].as_str().unwrap()),
            calls: calls.clone(),
        };
        let git = GitVcs::new(VcsProcess::with_runner(Arc::new(runner)));
        let registry = VcsRegistry::new(git, Arc::new(ManualClock::default()));
        for expected in scenario["results"].as_array().unwrap() {
            let step = &expected["step"];
            if let Some(path) = step["mkdir"].as_str() {
                std::fs::create_dir_all(root.join(path)).unwrap();
                continue;
            }
            if let Some(path) = step["rm"].as_str() {
                std::fs::remove_dir_all(root.join(path)).unwrap();
                continue;
            }
            calls.lock().unwrap().clear();
            let kind = step["kind"]
                .as_str()
                .map(|kind| VcsDriverKind::parse(kind).unwrap());
            let outcome: Result<Value, VcsError> = if let Some(kind) = step["get"].as_str() {
                registry
                    .driver(VcsDriverKind::parse(kind).unwrap())
                    .map(|_| json!(kind))
            } else if let Some(path) = step["detect"].as_str() {
                registry
                    .detect(root.join(path).to_str().unwrap(), kind)
                    .await
                    .map(handle_json(&root))
            } else {
                let path = step["resolve"].as_str().unwrap();
                registry
                    .resolve(root.join(path).to_str().unwrap(), kind)
                    .await
                    .map(|handle| handle_json(&root)(Some(handle)))
            };
            let (key, value) = match outcome {
                Ok(value) => ("ok", value),
                Err(error) => ("error", masked(vcs_error_wire(&error), &root)),
            };
            assert_eq!(value, expected[key], "{name}: {step}");
            assert!(
                expected
                    .get(if key == "ok" { "error" } else { "ok" })
                    .is_none(),
                "{name}: {step}"
            );
            assert_eq!(
                json!(*calls.lock().unwrap()),
                expected["calls"],
                "{name}: {step}"
            );
        }
    }
}

fn handle_json(root: &Path) -> impl Fn(Option<crate::vcs_registry::VcsHandle>) -> Value + '_ {
    move |handle| match handle {
        None => Value::Null,
        Some(handle) => json!({
            "kind": handle.kind.as_str(),
            "rootPath": relative_to(root, &handle.repository.root_path),
            "metadataPath": handle.repository.metadata_path,
        }),
    }
}
